select * from customer

-- 1.total revenue generated by male vs female customers
select customer.gender , SUM(purchase_amount) as revenue
from customer
group by gender

-- 2.Which customers used a discount but still spent more than average purchase amount
SELECT customer_id, discount_applied, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer)

-- 3. Top 5 products with the highest average review rating
Select item_purchased , Round(avg(review_rating::numeric) , 2) as avg_product_rating
from  customer
group by item_purchased
order by avg(review_rating) desc 
limit 5

-- 4. Compare the average Purchase Amounts between Standard and Express Shipping.
select shipping_type, Round(avg(purchase_amount),2)
from customer
where shipping_type in ('Standard' , 'Express')
group by shipping_type

-- 5. Do subscribed customers spend more? Compare average spend and total revenue between
--subscribers and non subscribers ? 

Select subscription_status ,count(customer_id) as total_customer , round(sum(purchase_amount),2) as revenue , round(avg(purchase_amount),2) as average_spend
from customer
group by subscription_status
order by revenue , average_spend desc

-- 6. Which 5 products have the highest number of purchases with discounts applied?
select item_purchased , 
round(100 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/ count(*) , 2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- 7. Segment customers into New , Returning and Loyal based on their
-- number of previous purchases , and show count of each segment
WITH customer_type AS (
    SELECT customer_id,
           previous_purchases,
           CASE
               WHEN previous_purchases = 1 THEN 'New'
               WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
               ELSE 'Loyal'
           END AS customer_segment
    FROM customer
)
SELECT customer_segment,
       COUNT(*) AS number_of_customers
FROM customer_type
GROUP BY customer_segment;

-- 8. Top 3 most purchased product within each category
with item_counts as (
select category , item_purchased , count(customer_id) as total_orders,
row_number() over (partition by category order by count(customer_id) desc) as item_rank
from customer
group by category , item_purchased
)
select item_rank , category , item_purchased , total_orders
from item_counts
where item_rank <=3

-- 9. Are customers who are repeat buyers(more than 5 previous purchases) also likely to subscribe?
select subscription_status , count(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status

-- 10. Whats the revenue contribution of each age group
select age_group , sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc
